const fs=require('node:fs');const fsp=require('node:fs/promises');const path=require('node:path');const os=require('node:os');const{pipeline}=require('node:stream/promises');const{randomUUID}=require('node:crypto');const{EpisodeBundleService}=require('./episode-bundle-service');
async function streamToFile(request,maxBytes){const dir=await fsp.mkdtemp(path.join(os.tmpdir(),'forge-upload-')),file=path.join(dir,`${randomUUID()}.forge-bundle.tar.gz`);let bytes=0;const limiter=async function*(){for await(const chunk of request){bytes+=chunk.length;if(bytes>maxBytes)throw Object.assign(new Error('bundle exceeds configured size limit'),{code:'BUNDLE_TOO_LARGE',statusCode:413});yield chunk}};try{await pipeline(limiter(),fs.createWriteStream(file,{mode:0o600}));return{dir,file,bytes}}catch(error){await fsp.rm(dir,{recursive:true,force:true});throw error}}
function json(res,status,body){if(res.headersSent)return;res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store'});res.end(JSON.stringify(body))}function status(error){return Number.isInteger(error.statusCode)?error.statusCode:error.code==='FORBIDDEN'?403:error.code==='NOT_FOUND'?404:error.code==='BUNDLE_TOO_LARGE'?413:error.code==='BUNDLE_SCHEMA_INCOMPATIBLE'?409:422}
function createEpisodeBundleHttp({pool,logger=console,service=null}={}){const bundleService=service||new EpisodeBundleService({pool,logger});return async function handle(request,response,{auth,projectAccess,hasRole,observability}={}){const url=new URL(request.url||'/','http://localhost'),pathname=url.pathname,projectMatch=/^\/v2\/projects\/([^/]+)\/export$/.exec(pathname),episodeMatch=/^\/v2\/episodes\/([^/]+)\/export$/.exec(pathname),importMatch=pathname==='/v2/bundles/import',replayMatch=/^\/v2\/episodes\/([^/]+)\/replay$/.exec(pathname);if(!projectMatch&&!episodeMatch&&!importMatch&&!replayMatch)return false;try{if(!auth)return json(response,401,{error:{code:'UNAUTHORIZED'}});if(projectMatch){if(request.method!=='GET')return json(response,405,{error:{code:'METHOD_NOT_ALLOWED'}});const projectId=decodeURIComponent(projectMatch[1]);if(!(await projectAccess(auth,projectId,'VIEWER')))return json(response,403,{error:{code:'FORBIDDEN'}});const result=await bundleService.exportBundle({projectId,tenantId:auth.tenantId,actor:auth.actor,configSnapshot:{node:process.version,service:'forge-studio',bundleSchemaVersion:1}});response.writeHead(200,{'content-type':'application/gzip','content-disposition':`attachment; filename="${result.bundleId}.forge-bundle.tar.gz"`,'content-length':String(result.sizeBytes),'x-bundle-id':result.bundleId,'x-bundle-sha256':result.sha256,'cache-control':'no-store'});await pipeline(fs.createReadStream(result.archive),response);await fsp.rm(path.dirname(result.archive),{recursive:true,force:true});return true}if(episodeMatch){if(request.method!=='GET')return json(response,405,{error:{code:'METHOD_NOT_ALLOWED'}});const episodeId=decodeURIComponent(episodeMatch[1]),project=(await pool.query('SELECT project_id FROM episodes WHERE id=$1',[episodeId])).rows[0];if(!project||!(await projectAccess(auth,project.project_id,'VIEWER')))return json(response,403,{error:{code:'FORBIDDEN'}});const result=await bundleService.exportBundle({projectId:project.project_id,episodeId,tenantId:auth.tenantId,actor:auth.actor,configSnapshot:{node:process.version,service:'forge-studio',bundleSchemaVersion:1}});response.writeHead(200,{'content-type':'application/gzip','content-disposition':`attachment; filename="${result.bundleId}.forge-bundle.tar.gz"`,'content-length':String(result.sizeBytes),'x-bundle-id':result.bundleId,'x-bundle-sha256':result.sha256,'cache-control':'no-store'});await pipeline(fs.createReadStream(result.archive),response);await fsp.rm(path.dirname(result.archive),{recursive:true,force:true});return true}if(importMatch){if(request.method!=='POST')return json(response,405,{error:{code:'METHOD_NOT_ALLOWED'}});if(!hasRole(auth,'EDITOR'))return json(response,403,{error:{code:'FORBIDDEN'}});const contentType=String(request.headers['content-type']||'').toLowerCase();if(!contentType.includes('gzip')&&!contentType.includes('forge-bundle')&&!contentType.includes('application/octet-stream'))return json(response,415,{error:{code:'UNSUPPORTED_MEDIA_TYPE'}});const uploaded=await streamToFile(request,bundleService.maxBytes);try{const result=await bundleService.importBundle({archivePath:uploaded.file,tenantId:auth.tenantId,actor:auth.actor,targetProjectId:url.searchParams.get('targetProjectId'),dryRun:url.searchParams.get('dryRun')==='true',allowMissingArtifacts:url.searchParams.get('allowMissingArtifacts')==='true'});return json(response,result.status==='QUARANTINED'?422:200,result)}finally{await fsp.rm(uploaded.dir,{recursive:true,force:true})}}if(replayMatch){if(request.method!=='POST')return json(response,405,{error:{code:'METHOD_NOT_ALLOWED'}});const episodeId=decodeURIComponent(replayMatch[1]),project=(await pool.query('SELECT project_id FROM episodes WHERE id=$1',[episodeId])).rows[0];if(!project||!(await projectAccess(auth,project.project_id,'EDITOR')))return json(response,403,{error:{code:'FORBIDDEN'}});const body=await readJson(request,256*1024),stageKind=body.stageKind;if(typeof stageKind!=='string'||!/^[a-z0-9:_-]{1,100}$/i.test(stageKind))return json(response,400,{error:{code:'INVALID_STAGE_KIND'}});return json(response,202,await bundleService.createReplay({tenantId:auth.tenantId,actor:auth.actor,episodeId,stageKind,sourceJobId:body.sourceJobId||null}))}}catch(error){observability?.metrics?.inc?.('forge_bundle_operations_total',{operation:importMatch?'import':replayMatch?'replay':'export',outcome:'error'});logger.warn?.({event:'episode_bundle.operation_failed',code:error.code,message:error.message});return json(response,status(error),{error:{code:error.code||'BUNDLE_OPERATION_FAILED',message:error.message}})}return true}}
async function readJson(request,maxBytes){let size=0;const chunks=[];for await(const chunk of request){size+=chunk.length;if(size>maxBytes)throw Object.assign(new Error('JSON body too large'),{code:'PAYLOAD_TOO_LARGE',statusCode:413});chunks.push(chunk)}try{return JSON.parse(Buffer.concat(chunks).toString('utf8')||'{}')}catch{throw Object.assign(new Error('Malformed JSON'),{code:'MALFORMED_JSON',statusCode:400})}}
module.exports={createEpisodeBundleHttp};
